G[21,27]=6
lab,n=label(G!=0)
marks={int(lab[r,c]):int(G[r,c]) for r,c in np.argwhere(G>1)}
print('components',n,'markers',marks)
from collections import Counter
print([(k,int((lab==k).sum())) for k in range(1,n+1)])
O=G.copy()
for r in range(1,29):
 for c in range(1,29):
  block=lab[r-1:r+2,c-1:c+2]
  if np.all(block==block[0,0]) and block[0,0] in marks:
   O[r,c]=marks[int(block[0,0])]
print(Counter(O.flatten()), 'changes',np.argwhere(O!=G).shape)
for r in range(30):
 if np.any(O[r]!=G[r]): print(r,[(int(c),int(G[r,c]),int(O[r,c])) for c in np.where(O[r]!=G[r])[0]])
